public class Main {
    static int f(int x) {
        int r = 0;
        switch (x) {
            case 1: r += 1;
            case 2: r += 2;
            default: r += 4;
        }
        return r;
    }
    public static void main(String[] args) {
        System.out.print(f(1) + ":" + f(2));
    }
}

public class Main {
    public static void main(String[] args) {
        int total = 0;
        outer:
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 4; j++) {
                if (j == 1) continue;
                if (i == 1 && j == 2) break outer;
                total++;
            }
        }
        System.out.print(total);
    }
}

class Boom {
    static int x = init();
    static int init() {
        System.out.print("I:");
        if (true) throw new RuntimeException("boom");
        return 1;
    }
}
public class Main {
    public static void main(String[] args) {
        try {
            System.out.print(Boom.x);
        } catch (Throwable e) {
            System.out.print(e.getClass().getSimpleName());
        }
    }
}

record Point(int x, int y) implements Comparable<Point> {
    @Override public int compareTo(Point other) {
        return Integer.compare(x + y, other.x + other.y);
    }
}
public class Main {
    public static void main(String[] args) {
        Point a = new Point(1, 4);
        Point b = new Point(2, 3);
        System.out.print(a.equals(b) + ":" + a.compareTo(b));
    }
}

class Base {
    static int count = 1;
    static void inc() { count++; }
}
class Sub extends Base {
    static int count = 10;
    static void inc() { count += 5; }
}
public class Main {
    public static void main(String[] args) {
        Base b = new Sub();
        b.inc();
        ((Sub)b).inc();
        System.out.print(Base.count + ":" + Sub.count);
    }
}

